import React, { useState, useEffect, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const StylistDashboard = () => {
  const { user, token, logout } = useAuth();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('today');
  const [appointments, setAppointments] = useState([]);
  const [earnings, setEarnings] = useState({ totalEarnings: 0, totalClients: 0 });
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [loading, setLoading] = useState(true);


  const fetchAppointments = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    const headers = { Authorization: `Bearer ${token}` };
    try {
      const res = await axios.get(`/api/appointments/stylist/${user._id}?date=${selectedDate}`, { headers });
      setAppointments(res.data);
    } catch (err) { console.error(err); }
    finally { setLoading(false); }
  }, [user, selectedDate, token]);

  const fetchEarnings = useCallback(async () => {
    if (!user) return;
    const headers = { Authorization: `Bearer ${token}` };
    try {
      const res = await axios.get(`/api/appointments/earnings/${user._id}?date=${selectedDate}`, { headers });
      setEarnings(res.data);
    } catch (err) { console.error(err); }
  }, [user, selectedDate, token]);

  useEffect(() => {
    if (!user || user.role !== 'stylist') { navigate('/login'); return; }
    fetchAppointments();
    fetchEarnings();
  }, [user, navigate, fetchAppointments, fetchEarnings]);

  const handleStatusChange = async (appointmentId, newStatus) => {
    const headers = { Authorization: `Bearer ${token}` };
    try {
      await axios.put(`/api/appointments/${appointmentId}/status`, { status: newStatus }, { headers });
      fetchAppointments();
      fetchEarnings();
    } catch (err) {
      alert(err.response?.data?.message || 'Error al actualizar estado');
    }
  };

  const handleLogout = () => { logout(); navigate('/login'); };

  const pending = appointments.filter(a => a.status === 'pending' || a.status === 'confirmed');
  const completed = appointments.filter(a => a.status === 'completed');
  const cancelled = appointments.filter(a => a.status === 'cancelled' || a.status === 'no-show');

  if (!user) return <div className="loading-screen"><div className="spinner"></div></div>;

  return (
    <div className="dashboard">
      {/* Sidebar */}
      <aside className="sidebar">
        <div className="sidebar-brand"><span>💈</span> BarberShop</div>
        <nav className="sidebar-nav">
          {[
            { id: 'today', icon: '📋', label: 'Citas del Día' },
            { id: 'history', icon: '📅', label: 'Historial' },
            { id: 'earnings', icon: '💰', label: 'Mis Ingresos' }
          ].map(tab => (
            <button key={tab.id} className={`sidebar-link ${activeTab === tab.id ? 'active' : ''}`} onClick={() => setActiveTab(tab.id)}>
              <span className="icon">{tab.icon}</span> {tab.label}
            </button>
          ))}
        </nav>
        <div className="sidebar-user">
          <div className="sidebar-user-info">
            <div className="avatar">{user.name?.[0]}</div>
            <div><div className="name">{user.name}</div><div className="role">Estilista</div></div>
          </div>
          <button className="sidebar-link" onClick={handleLogout}><span className="icon">🚪</span> Cerrar Sesión</button>
        </div>
      </aside>

      {/* Mobile Nav */}
      <div className="mobile-nav">
        {[
          { id: 'today', icon: '📋', label: 'Hoy' },
          { id: 'history', icon: '📅', label: 'Historial' },
          { id: 'earnings', icon: '💰', label: 'Ingresos' }
        ].map(tab => (
          <button key={tab.id} className={activeTab === tab.id ? 'active' : ''} onClick={() => setActiveTab(tab.id)}>
            <span className="icon">{tab.icon}</span> {tab.label}
          </button>
        ))}
      </div>

      {/* Main Content */}
      <main className="dashboard-main">
        {/* Date Selector */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '24px', flexWrap: 'wrap', gap: '16px' }}>
          <h2>
            {activeTab === 'today' && 'Mis Citas'}
            {activeTab === 'history' && 'Historial de Citas'}
            {activeTab === 'earnings' && 'Mis Ingresos'}
          </h2>
          <div className="form-group" style={{ flexDirection: 'row', alignItems: 'center', gap: '10px' }}>
            <label style={{ margin: 0, whiteSpace: 'nowrap' }}>📅 Fecha:</label>
            <input type="date" value={selectedDate} onChange={(e) => setSelectedDate(e.target.value)} style={{ width: 'auto' }} />
          </div>
        </div>

        {/* Stats */}
        <div className="stats-grid">
          <div className="stat-card warning"><div className="stat-icon">⏳</div><div className="stat-value">{pending.length}</div><div className="stat-label">En Espera</div></div>
          <div className="stat-card success"><div className="stat-icon">✅</div><div className="stat-value">{completed.length}</div><div className="stat-label">Atendidos</div></div>
          <div className="stat-card gold"><div className="stat-icon">💰</div><div className="stat-value">S/ {earnings.totalEarnings}</div><div className="stat-label">Ingresos del Día</div></div>
          <div className="stat-card info"><div className="stat-icon">👥</div><div className="stat-value">{appointments.length}</div><div className="stat-label">Total Citas</div></div>
        </div>

        {/* TODAY TAB / HISTORY TAB */}
        {(activeTab === 'today' || activeTab === 'history') && (
          <div>
            {loading ? (
              <div className="loading-screen" style={{ minHeight: '30vh' }}><div className="spinner"></div></div>
            ) : appointments.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px 20px', color: 'var(--text-muted)' }}>
                <p style={{ fontSize: '3rem', marginBottom: '12px' }}>📭</p>
                <p>No hay citas programadas para esta fecha</p>
              </div>
            ) : (
              <div>
                {/* Pending Appointments */}
                {pending.length > 0 && (
                  <div style={{ marginBottom: '2rem' }}>
                    <h3 style={{ marginBottom: '16px', color: 'var(--warning)' }}>⏳ En Espera ({pending.length})</h3>
                    <table className="data-table">
                      <thead><tr><th>Cliente</th><th>Teléfono</th><th>Servicio</th><th>Hora</th><th>Precio</th><th>Acciones</th></tr></thead>
                      <tbody>
                        {pending.map(a => (
                          <tr key={a._id}>
                            <td><strong>{a.clientName}</strong></td>
                            <td>{a.clientPhone}</td>
                            <td>{a.service?.name}</td>
                            <td>{a.startTime} - {a.endTime}</td>
                            <td style={{ color: 'var(--gold)' }}>S/ {a.price}</td>
                            <td>
                              <div style={{ display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                                <button className="btn btn-success btn-sm" onClick={() => handleStatusChange(a._id, 'completed')}>✅ Atendido</button>
                                <button className="btn btn-danger btn-sm" onClick={() => handleStatusChange(a._id, 'cancelled')}>✖ Cancelar</button>
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}

                {/* Completed */}
                {completed.length > 0 && (
                  <div style={{ marginBottom: '2rem' }}>
                    <h3 style={{ marginBottom: '16px', color: 'var(--success)' }}>✅ Atendidos ({completed.length})</h3>
                    <table className="data-table">
                      <thead><tr><th>Cliente</th><th>Servicio</th><th>Hora</th><th>Precio</th><th>Estado</th></tr></thead>
                      <tbody>
                        {completed.map(a => (
                          <tr key={a._id}>
                            <td>{a.clientName}</td>
                            <td>{a.service?.name}</td>
                            <td>{a.startTime} - {a.endTime}</td>
                            <td style={{ color: 'var(--gold)' }}>S/ {a.price}</td>
                            <td><span className="badge badge-completed">Completado</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}

                {/* Cancelled */}
                {cancelled.length > 0 && (
                  <div>
                    <h3 style={{ marginBottom: '16px', color: 'var(--danger)' }}>✖ Cancelados ({cancelled.length})</h3>
                    <table className="data-table">
                      <thead><tr><th>Cliente</th><th>Servicio</th><th>Hora</th><th>Estado</th></tr></thead>
                      <tbody>
                        {cancelled.map(a => (
                          <tr key={a._id}>
                            <td>{a.clientName}</td>
                            <td>{a.service?.name}</td>
                            <td>{a.startTime}</td>
                            <td><span className="badge badge-cancelled">Cancelado</span></td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* EARNINGS TAB */}
        {activeTab === 'earnings' && (
          <div>
            <div style={{ background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '40px', textAlign: 'center', marginBottom: '2rem' }}>
              <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '2px', marginBottom: '8px' }}>Ingresos del Día</p>
              <p style={{ fontSize: '3.5rem', fontWeight: 700, fontFamily: 'Playfair Display, serif', color: 'var(--gold)', marginBottom: '8px' }}>S/ {earnings.totalEarnings}</p>
              <p style={{ color: 'var(--text-secondary)' }}>{earnings.totalClients} cliente{earnings.totalClients !== 1 ? 's' : ''} atendido{earnings.totalClients !== 1 ? 's' : ''}</p>
            </div>

            {earnings.appointments && earnings.appointments.length > 0 && (
              <div>
                <h3 style={{ marginBottom: '16px' }}>Detalle de Servicios Completados</h3>
                <table className="data-table">
                  <thead><tr><th>Cliente</th><th>Servicio</th><th>Hora</th><th>Monto</th></tr></thead>
                  <tbody>
                    {earnings.appointments.map(a => (
                      <tr key={a._id}>
                        <td>{a.clientName}</td>
                        <td>{a.service?.name}</td>
                        <td>{a.startTime}</td>
                        <td style={{ color: 'var(--gold)', fontWeight: 600 }}>S/ {a.price}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}
      </main>
    </div>
  );
};

export default StylistDashboard;
